mapper.select:
SELECT /* LGVPAY00001.retrieveContractSalaryData */ TO_CHAR(NVL(a.probation_period_odwg_amount, 0), 'FM999,999,999,999,990') AS probation_period_odwg_amount /*Prob. Sal/Old Sal.*/ , TO_CHAR(NVL(a.ordinary_wages_amount , 0), 'FM999,999,999,999,990') AS ordinary_wages_amount /*Nor.Sal/New Sal.*/
/* annual leave info */ ,(select TO_CHAR(NVL(al.use_annual_leave_days, 0), 'FM9990.0') FROM tb_att_annual_leave_n al WHERE al.employee_no = a.employee_no AND al.time_and_attendance_yyyymm = TO_CHAR(TO_DATE(#{payMonth}, 'MM/YYYY'), 'YYYYMM')) AS use_al_days /* 사용연차 */
,(select TO_CHAR(NVL(al.residual_annual_leave_days, 0) + NVL(al.annual_compensation_days, 0), 'FM9990.0') FROM tb_att_annual_leave_n al WHERE al.employee_no = a.employee_no AND al.time_and_attendance_yyyymm = TO_CHAR(TO_DATE(#{payMonth}, 'MM/YYYY'), 'YYYYMM')) AS remain_al_days /* 잔여연차 */ ,(SELECT COUNT(*) FROM tb_pay_emp_family_n pef WHERE pef.employee_no = a.employee_no AND pef.dependent_flag = 'Y') AS dependant_count_pay FROM tb_pay_result_s a WHERE a.payroll_calculation_exec_id = #{payrollCalculationExecId, jdbcType=NUMERIC} AND a.employee_no = #{employeeNo}

SELECT /* LGVPAY00001.retrieveSalaryChangeInfoList */
       TO_CHAR(b.basis_start_date, 'DD/MM/YYYY')                       AS start_date
     , TO_CHAR(SUM(pdc1.payment_base_amount), 'FM999,999,999,999,990') AS base_amount
FROM   tb_pay_detail_calc_t pdc1
     ,(SELECT DISTINCT pdc.basis_start_date
       FROM   tb_pay_detail_calc_t pdc
       WHERE  pdc.payroll_calculation_exec_id = #{payrollCalculationExecId, jdbcType=NUMERIC}
       AND    pdc.employee_no = #{employeeNo}
      ) b
WHERE  pdc1.payroll_calculation_exec_id = #{payrollCalculationExecId, jdbcType=NUMERIC}
AND    pdc1.employee_no = #{employeeNo}
AND    b.basis_start_date BETWEEN pdc1.basis_start_date AND pdc1.basis_end_date
GROUP BY b.basis_start_date
